const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const hudsonBayPoint = ee.Geometry.Point([-87.160422, 56.271030]);
  const hudsonBayRegion = hudsonBayPoint.buffer(100000); // 100km buffer around point

  const date1 = '2020-07-13';
  const date2 = '2020-07-29';

  // 2. Data Acquisition - MODIS Terra for daily coverage
  function getMODISCollection(date) {
    return ee.ImageCollection('MODIS/006/MOD09GA')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(hudsonBayRegion);
  }

  const col1 = getMODISCollection(date1);
  const col2 = getMODISCollection(date2);

  // Check if collections have data
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`${date1} Images: ${size1}`);
  console.log(`${date2} Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Simple ice detection using NDSI and brightness
  function detectIce(img) {
    // Calculate NDSI (Normalized Difference Snow Index)
    const ndsi = img.normalizedDifference(['sur_refl_b04', 'sur_refl_b06']);

    // Use band 1 (red) for brightness threshold
    const brightness = img.select('sur_refl_b01');

    // Simple ice detection: high NDSI and high brightness
    const iceMask = ndsi.gt(0.4).and(brightness.gt(1000));

    return img.addBands(iceMask.rename('ice_mask'));
  }

  const img1 = detectIce(col1.first());
  const img2 = detectIce(col2.first());

  // 4. Count ice pixels
  const count1 = img1.select('ice_mask').reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: hudsonBayRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('ice_mask').getInfo();

  const count2 = img2.select('ice_mask').reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: hudsonBayRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('ice_mask').getInfo();

  console.log(`${date1} Ice Pixels: ${count1}`);
  console.log(`${date2} Ice Pixels: ${count2}`);

  // 5. Validation & Final Answer
  if (count1 === null || count2 === null || 
      isNaN(count1) || isNaN(count2) ||
      count1 < 0 || count2 < 0) {
    console.log("<answer>C3</answer>");
  } else if (count1 === 0 && count2 === 0) {
    console.log("<answer>C2</answer>");
  } else if (count2 > count1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
